{"version":3,"file":"detail.js","sources":["pages/doctor/patients/detail.vue","../../../../../../../HBuilderX/plugins/uniapp-cli-vite/uniPage:/cGFnZXMvZG9jdG9yL3BhdGllbnRzL2RldGFpbC52dWU"],"sourcesContent":["<template>\n  <view class=\"patient-detail-page\">\n    <!-- 返回按钮 -->\n    <view class=\"back-section\" @click=\"goBackToPatientList\">\n      <text class=\"back-icon\">‹</text>\n      <text class=\"back-text\">返回患者列表</text>\n    </view>\n\n    <!-- 患者基本信息卡片 -->\n    <view class=\"info-card\">\n      <view class=\"card-header\">\n        <text class=\"card-title\">基本信息</text>\n      </view>\n      <view class=\"info-grid\">\n        <view class=\"info-item\">\n          <text class=\"info-label\">姓名</text>\n          <text class=\"info-value\">{{ patient.name }}</text>\n        </view>\n        <view class=\"info-item\">\n          <text class=\"info-label\">性别</text>\n          <text class=\"info-value\">{{ patient.gender }}</text>\n        </view>\n        <view class=\"info-item\">\n          <text class=\"info-label\">年龄</text>\n          <text class=\"info-value\">{{ patient.age }}岁</text>\n        </view>\n        <view class=\"info-item\">\n          <text class=\"info-label\">身份</text>\n          <text class=\"info-value\">{{ patient.identity }}</text>\n        </view>\n        <view class=\"info-item full-width\">\n          <text class=\"info-label\">联系方式</text>\n          <text class=\"info-value\">{{ patient.phone }}</text>\n        </view>\n      </view>\n    </view>\n\n    <!-- 挂号信息卡片 -->\n    <view class=\"info-card\">\n      <view class=\"card-header\">\n        <text class=\"card-title\">挂号信息</text>\n        <view class=\"status-badge\" :class=\"getStatusClass(patient.status)\">\n          {{ patient.status }}\n        </view>\n      </view>\n      <view class=\"info-list\">\n        <view class=\"list-item\">\n          <text class=\"item-label\">挂号号码</text>\n          <text class=\"item-value\">{{ patient.registrationNumber }}</text>\n        </view>\n        <view class=\"list-item\">\n          <text class=\"item-label\">预约时段</text>\n          <text class=\"item-value\">{{ patient.appointmentTime }}</text>\n        </view>\n        <view class=\"list-item\">\n          <text class=\"item-label\">就诊科室</text>\n          <text class=\"item-value\">{{ patient.department }}</text>\n        </view>\n        <view class=\"list-item\">\n          <text class=\"item-label\">就诊医生</text>\n          <text class=\"item-value\">{{ patient.doctor }}</text>\n        </view>\n      </view>\n    </view>\n\n    <!-- 既往病史卡片 -->\n    <view class=\"info-card\">\n      <view class=\"card-header\">\n        <text class=\"card-title\">既往病史</text>\n        <text class=\"privacy-tip\">（脱敏展示）</text>\n      </view>\n      <view v-if=\"patient.medicalHistory && patient.medicalHistory.length > 0\" class=\"history-list\">\n        <view\n          v-for=\"(history, index) in patient.medicalHistory\"\n          :key=\"index\"\n          class=\"history-item\"\n        >\n          <view class=\"history-tag\">{{ history.type }}</view>\n          <text class=\"history-text\">{{ history.description }}</text>\n        </view>\n      </view>\n      <view v-else class=\"empty-history\">\n        <text class=\"empty-text\">暂无既往病史记录</text>\n      </view>\n    </view>\n\n    <!-- 就诊历史卡片 -->\n    <view class=\"info-card\">\n      <view class=\"card-header\">\n        <text class=\"card-title\">就诊历史</text>\n      </view>\n      <view v-if=\"patient.visitHistory && patient.visitHistory.length > 0\" class=\"visit-list\">\n        <view\n          v-for=\"(visit, index) in patient.visitHistory\"\n          :key=\"index\"\n          class=\"visit-item\"\n          @click=\"viewVisitDetail(visit)\"\n        >\n          <view class=\"visit-header\">\n            <view class=\"visit-date\">\n              <text class=\"date-icon\">📅</text>\n              <text class=\"date-text\">{{ visit.date }}</text>\n            </view>\n            <text class=\"visit-arrow\">›</text>\n          </view>\n          <view class=\"visit-info\">\n            <text class=\"visit-dept\">{{ visit.department }}</text>\n            <text class=\"visit-doctor\">{{ visit.doctor }}</text>\n          </view>\n          <view v-if=\"visit.diagnosis\" class=\"visit-diagnosis\">\n            <text class=\"diagnosis-label\">诊断：</text>\n            <text class=\"diagnosis-text\">{{ visit.diagnosis }}</text>\n          </view>\n        </view>\n      </view>\n      <view v-else class=\"empty-history\">\n        <text class=\"empty-text\">暂无就诊历史</text>\n      </view>\n    </view>\n\n    <!-- 操作按钮区域 -->\n    <view v-if=\"patient.status !== '已完成'\" class=\"action-section\">\n      <button\n        v-if=\"patient.status === '待接诊'\"\n        class=\"action-btn receive-btn\"\n        @click=\"receivePatient\"\n      >\n        开始接诊\n      </button>\n      <button\n        v-else-if=\"patient.status === '接诊中'\"\n        class=\"action-btn complete-btn\"\n        @click=\"completePatient\"\n      >\n        完成接诊\n      </button>\n    </view>\n\n    <!-- 备注输入区域 -->\n    <view v-if=\"patient.status === '接诊中'\" class=\"note-section\">\n      <view class=\"note-header\">\n        <text class=\"note-title\">就诊备注</text>\n      </view>\n      <textarea\n        class=\"note-textarea\"\n        v-model=\"visitNote\"\n        placeholder=\"请输入就诊情况、诊断结果等信息...\"\n        maxlength=\"500\"\n      />\n      <view class=\"note-footer\">\n        <text class=\"char-count\">{{ visitNote.length }}/500</text>\n        <button class=\"save-note-btn\" @click=\"saveNote\">保存备注</button>\n      </view>\n    </view>\n  </view>\n</template>\n\n<script setup>\nimport { ref, onMounted } from 'vue'\nimport { onLoad } from '@dcloudio/uni-app'\nimport { uniNavigateTo, uniShowToast } from '@/utils/uniHelper'\nimport { doctorApi } from '@/api/doctor'\n\n// 患者详情数据（加载后会用后端数据覆盖）\nconst patient = ref({\n  name: '张**',\n  gender: '男',\n  age: 22,\n  identity: '学生',\n  phone: '138****5678',\n  registrationNumber: 'R2024101101',\n  appointmentTime: '2024-10-11 08:00-08:30',\n  department: '内科',\n  doctor: '张医生',\n  status: '待接诊',\n  medicalHistory: [\n    { type: '过敏史', description: '青霉素过敏' },\n    { type: '慢性病', description: '轻度高血压（已控制）' }\n  ],\n  visitHistory: [\n    { date: '2024-09-15', department: '内科', doctor: '李医生', diagnosis: '急性上呼吸道感染' },\n    { date: '2024-07-20', department: '骨科', doctor: '王医生', diagnosis: '踝关节扭伤' }\n  ]\n})\n\nconst visitNote = ref('')\n\nconst getStatusClass = (status) => {\n  if (status === '待接诊') return 'status-pending'\n  if (status === '接诊中') return 'status-progress'\n  if (status === '已完成') return 'status-done'\n  return 'status-pending'\n}\n\n// 工具：计算年龄\n// 移除 TS 泛型与类型注解\nconst patientIdRef = ref(null)\nconst appointmentIdRef = ref(null)\n\n// 工具：计算年龄（移除参数类型注解）\nconst calcAge = (birthDate) => {\n  if (!birthDate) return ''\n  try {\n    const d = new Date(birthDate)\n    const now = new Date()\n    let age = now.getFullYear() - d.getFullYear()\n    const m = now.getMonth() - d.getMonth()\n    if (m < 0 || (m === 0 && now.getDate() < d.getDate())) age--\n    return age\n  } catch { return '' }\n}\n\n// 工具：患者身份映射\nconst mapIdentity = (type) => {\n  if (type === 1) return '学生'\n  if (type === 2) return '教师'\n  if (type === 3) return '职工'\n  return '其他'\n}\n\n// 加载后端患者详情\nasync function loadPatientDetail(id) {\n  try {\n    const detail = await doctorApi.getPatientDetail(id)\n    const p = detail?.patient || {}\n    const visits = Array.isArray(detail?.visits) ? detail.visits : []\n\n    const statusMap = (s) => s === 2 ? '已完成' : (s === 1 ? '接诊中' : '待接诊')\n    const latestStatus = visits.length > 0 ? statusMap(visits[0]?.status) : '待接诊'\n\n    patient.value = {\n      name: p.patientName || p.name || '',\n      gender: p.gender || '',\n      age: calcAge(p.birthDate),\n      identity: mapIdentity(p.patientType),\n      phone: p.phone || '',\n      registrationNumber: (visits[0]?.visitNo) || (appointmentIdRef.value ? String(appointmentIdRef.value) : ''),\n      appointmentTime: visits[0]?.timeSlot || '',\n      department: '', // 后端当前VO未返回科室名（只有 deptId），先留空\n      doctor: '', // 同理 doctorId -> 名称未返回，先留空\n      status: latestStatus,\n      medicalHistory: [], // 暂无病史字段，留空\n      visitHistory: visits.map(v => ({\n        date: v.visitDate,\n        department: '', // 仅有 deptId，页面先留空\n        doctor: '', // 仅有 doctorId，页面先留空\n        diagnosis: v.diagnosis || ''\n      }))\n    }\n  } catch (e) {\n    uniShowToast({ title: '获取患者详情失败', icon: 'none' })\n  }\n}\n\nfunction goBackToPatientList() {\n  const pages = getCurrentPages()\n  if (pages.length > 1) {\n    uni.navigateBack()\n  } else {\n    uniNavigateTo('/pages/doctor/patients/list')\n  }\n}\n\n// 开始接诊：调用后端更新状态\nasync function receivePatient() {\n  if (!appointmentIdRef.value) {\n    uniShowToast({ title: '缺少预约ID', icon: 'none' })\n    return\n  }\n  try {\n    await doctorApi.updatePatientStatus(appointmentIdRef.value, 'start')\n    patient.value.status = '接诊中'\n    uniShowToast({ title: '已开始接诊', icon: 'success' })\n  } catch {\n    uniShowToast({ title: '开始接诊失败', icon: 'none' })\n  }\n}\n\n// 完成接诊：调用后端更新状态\nasync function completePatient() {\n  if (!appointmentIdRef.value) {\n    uniShowToast({ title: '缺少预约ID', icon: 'none' })\n    return\n  }\n  try {\n    await doctorApi.updatePatientStatus(appointmentIdRef.value, 'finish')\n    patient.value.status = '已完成'\n    uniShowToast({ title: '已完成接诊', icon: 'success' })\n  } catch {\n    uniShowToast({ title: '完成接诊失败', icon: 'none' })\n  }\n}\n\nfunction saveNote() {\n  if (!visitNote.value) {\n    uniShowToast({ title: '请输入备注内容', icon: 'none' })\n    return\n  }\n  uniShowToast({ title: '备注已保存', icon: 'success' })\n}\n\nfunction viewVisitDetail(visit) {\n  uniShowToast({ title: `就诊记录：${visit.date}`, icon: 'none' })\n}\n\n// URL 参数传入（patient=encodeURIComponent(JSON.stringify(obj))）\nonLoad((options) => {\n  try {\n    if (options && options.patient) {\n      const incoming = JSON.parse(decodeURIComponent(options.patient))\n      patient.value = { ...patient.value, ...incoming }\n    }\n  } catch (e) {\n    // ignore parse error\n  }\n  if (options?.id) {\n    patientIdRef.value = Number(options.id)\n  }\n  if (options?.appointmentId) {\n    appointmentIdRef.value = Number(options.appointmentId)\n  }\n})\n\n// EventChannel 传入（保持兼容）\nonMounted(async () => {\n  const pages = getCurrentPages()\n  const cur = pages[pages.length - 1]\n  if (cur && cur.getOpenerEventChannel) {\n    const ec = cur.getOpenerEventChannel()\n    if (ec) {\n      ec.on('patient', (data) => {\n        if (data) patient.value = { ...patient.value, ...data }\n      })\n      ec.on('sendPatient', (data) => {\n        if (data?.patient) {\n          patient.value = { ...patient.value, ...data.patient }\n        }\n      })\n    }\n  }\n  // 若URL带了id，加载后端详情\n  if (patientIdRef.value) {\n    await loadPatientDetail(patientIdRef.value)\n  }\n})\n</script>\n\n<style scoped>\n.patient-detail-page {\n  min-height: 100vh;\n  box-sizing: border-box;\n  padding: 24rpx;\n  background: linear-gradient(180deg, #e9f2ff 0%, #f7f9fc 100%);\n}\n\n/* 返回 */\n.back-section {\n  display: flex;\n  align-items: center;\n  color: #2a7bff;\n  font-weight: 600;\n  margin-bottom: 20rpx;\n}\n.back-icon {\n  font-size: 40rpx;\n  margin-right: 8rpx;\n}\n.back-text {\n  font-size: 28rpx;\n}\n\n/* 卡片通用 */\n.info-card {\n  background: #fff;\n  border-radius: 16rpx;\n  padding: 24rpx;\n  box-shadow: 0 8rpx 24rpx rgba(42, 123, 255, 0.08);\n  margin-bottom: 24rpx;\n}\n.card-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 12rpx;\n}\n.card-title {\n  font-size: 32rpx;\n  font-weight: 700;\n  color: #1a1a1a;\n}\n\n/* 状态徽标 */\n.status-badge {\n  padding: 8rpx 16rpx;\n  border-radius: 999rpx;\n  font-size: 24rpx;\n  font-weight: 600;\n}\n.status-pending {\n  color: #8a6d3b;\n  background: #fff3cd;\n}\n.status-progress {\n  color: #0f5132;\n  background: #d1e7dd;\n}\n.status-done {\n  color: #084298;\n  background: #cfe2ff;\n}\n\n/* 基本信息网格 */\n.info-grid {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 16rpx;\n}\n.info-item {\n  width: calc(50% - 8rpx);\n  background: #f8fafc;\n  border-radius: 12rpx;\n  padding: 16rpx;\n}\n.info-item.full-width {\n  width: 100%;\n}\n.info-label {\n  font-size: 24rpx;\n  color: #7a8aa0;\n}\n.info-value {\n  margin-top: 6rpx;\n  font-size: 28rpx;\n  color: #2f3b52;\n  font-weight: 600;\n}\n\n/* 列表信息 */\n.info-list {\n  display: flex;\n  flex-direction: column;\n  gap: 12rpx;\n}\n.list-item {\n  display: flex;\n  justify-content: space-between;\n  padding: 16rpx;\n  background: #f8fafc;\n  border-radius: 12rpx;\n}\n.item-label {\n  color: #7a8aa0;\n  font-size: 24rpx;\n}\n.item-value {\n  color: #2f3b52;\n  font-size: 28rpx;\n  font-weight: 600;\n}\n\n/* 病史 */\n.privacy-tip {\n  color: #7a8aa0;\n  font-size: 24rpx;\n  margin-left: 8rpx;\n}\n.history-list {\n  display: flex;\n  flex-direction: column;\n  gap: 12rpx;\n}\n.history-item {\n  display: flex;\n  align-items: center;\n  gap: 12rpx;\n  background: #f8fafc;\n  padding: 16rpx;\n  border-radius: 12rpx;\n}\n.history-tag {\n  background: #e9f2ff;\n  color: #2a7bff;\n  font-size: 22rpx;\n  border-radius: 999rpx;\n  padding: 6rpx 12rpx;\n}\n.history-text {\n  font-size: 26rpx;\n  color: #2f3b52;\n}\n.empty-history {\n  padding: 24rpx;\n  text-align: center;\n  color: #7a8aa0;\n}\n.empty-text {\n  font-size: 26rpx;\n}\n\n/* 就诊历史 */\n.visit-list {\n  display: flex;\n  flex-direction: column;\n  gap: 16rpx;\n}\n.visit-item {\n  background: #f8fafc;\n  border-radius: 12rpx;\n  padding: 16rpx;\n}\n.visit-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 8rpx;\n}\n.visit-date {\n  display: flex;\n  align-items: center;\n  gap: 8rpx;\n  color: #2f3b52;\n  font-weight: 600;\n}\n.date-icon {\n  font-size: 28rpx;\n}\n.date-text {\n  font-size: 28rpx;\n}\n.visit-arrow {\n  font-size: 40rpx;\n  color: #a0b7e0;\n}\n.visit-info {\n  display: flex;\n  justify-content: space-between;\n  color: #7a8aa0;\n  font-size: 24rpx;\n}\n.visit-diagnosis {\n  margin-top: 8rpx;\n  font-size: 24rpx;\n  color: #7a8aa0;\n}\n.diagnosis-label {\n  font-weight: 600;\n}\n.diagnosis-text {\n  color: #2f3b52;\n}\n\n/* 操作区 */\n.action-section {\n  margin: 24rpx 0;\n  display: flex;\n  gap: 16rpx;\n}\n.action-btn {\n  flex: 1;\n  border: none;\n  border-radius: 12rpx;\n  padding: 24rpx 0;\n  color: #fff;\n  font-size: 28rpx;\n  font-weight: 700;\n}\n.receive-btn {\n  background: linear-gradient(90deg, #2a7bff, #6aa9ff);\n  box-shadow: 0 12rpx 20rpx rgba(42, 123, 255, 0.24);\n}\n.complete-btn {\n  background: linear-gradient(90deg, #00c853, #52e176);\n  box-shadow: 0 12rpx 20rpx rgba(0, 200, 83, 0.24);\n}\n\n/* 备注区 */\n.note-section {\n  background: #fff;\n  border-radius: 16rpx;\n  padding: 24rpx;\n  box-shadow: 0 8rpx 24rpx rgba(42, 123, 255, 0.08);\n}\n.note-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 12rpx;\n}\n.note-title {\n  font-size: 32rpx;\n  font-weight: 700;\n  color: #1a1a1a;\n}\n.note-textarea {\n  width: 100%;\n  min-height: 160rpx;\n  background: #f8fafc;\n  border-radius: 12rpx;\n  padding: 16rpx;\n  font-size: 26rpx;\n  color: #2f3b52;\n  box-sizing: border-box;\n}\n.note-footer {\n  margin-top: 12rpx;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n.char-count {\n  font-size: 24rpx;\n  color: #7a8aa0;\n}\n.save-note-btn {\n  background: linear-gradient(90deg, #2a7bff, #6aa9ff);\n  color: #fff;\n  border: none;\n  border-radius: 12rpx;\n  padding: 16rpx 24rpx;\n  font-size: 26rpx;\n  font-weight: 700;\n}\n</style>","import MiniProgramPage from 'D:/HuaweiMoveData/Users/zheng/Documents/GitHub/lh7772/校医院挂号系统/pages/doctor/patients/detail.vue'\nwx.createPage(MiniProgramPage)"],"names":["ref","doctorApi","uniShowToast","uni","uniNavigateTo","onLoad","onMounted"],"mappings":";;;;;;;AAoKA,UAAM,UAAUA,cAAAA,IAAI;AAAA,MAClB,MAAM;AAAA,MACN,QAAQ;AAAA,MACR,KAAK;AAAA,MACL,UAAU;AAAA,MACV,OAAO;AAAA,MACP,oBAAoB;AAAA,MACpB,iBAAiB;AAAA,MACjB,YAAY;AAAA,MACZ,QAAQ;AAAA,MACR,QAAQ;AAAA,MACR,gBAAgB;AAAA,QACd,EAAE,MAAM,OAAO,aAAa,QAAS;AAAA,QACrC,EAAE,MAAM,OAAO,aAAa,aAAc;AAAA,MAC3C;AAAA,MACD,cAAc;AAAA,QACZ,EAAE,MAAM,cAAc,YAAY,MAAM,QAAQ,OAAO,WAAW,WAAY;AAAA,QAC9E,EAAE,MAAM,cAAc,YAAY,MAAM,QAAQ,OAAO,WAAW,QAAS;AAAA,MAC5E;AAAA,IACH,CAAC;AAED,UAAM,YAAYA,cAAG,IAAC,EAAE;AAExB,UAAM,iBAAiB,CAAC,WAAW;AACjC,UAAI,WAAW;AAAO,eAAO;AAC7B,UAAI,WAAW;AAAO,eAAO;AAC7B,UAAI,WAAW;AAAO,eAAO;AAC7B,aAAO;AAAA,IACT;AAIA,UAAM,eAAeA,cAAG,IAAC,IAAI;AAC7B,UAAM,mBAAmBA,cAAG,IAAC,IAAI;AAGjC,UAAM,UAAU,CAAC,cAAc;AAC7B,UAAI,CAAC;AAAW,eAAO;AACvB,UAAI;AACF,cAAM,IAAI,IAAI,KAAK,SAAS;AAC5B,cAAM,MAAM,oBAAI,KAAM;AACtB,YAAI,MAAM,IAAI,YAAW,IAAK,EAAE,YAAa;AAC7C,cAAM,IAAI,IAAI,SAAQ,IAAK,EAAE,SAAU;AACvC,YAAI,IAAI,KAAM,MAAM,KAAK,IAAI,QAAO,IAAK,EAAE,QAAS;AAAG;AACvD,eAAO;AAAA,MACX,QAAU;AAAE,eAAO;AAAA,MAAI;AAAA,IACvB;AAGA,UAAM,cAAc,CAAC,SAAS;AAC5B,UAAI,SAAS;AAAG,eAAO;AACvB,UAAI,SAAS;AAAG,eAAO;AACvB,UAAI,SAAS;AAAG,eAAO;AACvB,aAAO;AAAA,IACT;AAGA,mBAAe,kBAAkB,IAAI;;AACnC,UAAI;AACF,cAAM,SAAS,MAAMC,qBAAU,iBAAiB,EAAE;AAClD,cAAM,KAAI,iCAAQ,YAAW,CAAE;AAC/B,cAAM,SAAS,MAAM,QAAQ,iCAAQ,MAAM,IAAI,OAAO,SAAS,CAAE;AAEjE,cAAM,YAAY,CAAC,MAAM,MAAM,IAAI,QAAS,MAAM,IAAI,QAAQ;AAC9D,cAAM,eAAe,OAAO,SAAS,IAAI,WAAU,YAAO,CAAC,MAAR,mBAAW,MAAM,IAAI;AAExE,gBAAQ,QAAQ;AAAA,UACd,MAAM,EAAE,eAAe,EAAE,QAAQ;AAAA,UACjC,QAAQ,EAAE,UAAU;AAAA,UACpB,KAAK,QAAQ,EAAE,SAAS;AAAA,UACxB,UAAU,YAAY,EAAE,WAAW;AAAA,UACnC,OAAO,EAAE,SAAS;AAAA,UAClB,sBAAqB,YAAO,CAAC,MAAR,mBAAW,aAAa,iBAAiB,QAAQ,OAAO,iBAAiB,KAAK,IAAI;AAAA,UACvG,mBAAiB,YAAO,CAAC,MAAR,mBAAW,aAAY;AAAA,UACxC,YAAY;AAAA;AAAA,UACZ,QAAQ;AAAA;AAAA,UACR,QAAQ;AAAA,UACR,gBAAgB,CAAE;AAAA;AAAA,UAClB,cAAc,OAAO,IAAI,QAAM;AAAA,YAC7B,MAAM,EAAE;AAAA,YACR,YAAY;AAAA;AAAA,YACZ,QAAQ;AAAA;AAAA,YACR,WAAW,EAAE,aAAa;AAAA,UAClC,EAAQ;AAAA,QACH;AAAA,MACF,SAAQ,GAAG;AACVC,wBAAAA,aAAa,EAAE,OAAO,YAAY,MAAM,OAAM,CAAE;AAAA,MACjD;AAAA,IACH;AAEA,aAAS,sBAAsB;AAC7B,YAAM,QAAQ,gBAAiB;AAC/B,UAAI,MAAM,SAAS,GAAG;AACpBC,sBAAAA,MAAI,aAAc;AAAA,MACtB,OAAS;AACLC,wBAAAA,cAAc,6BAA6B;AAAA,MAC5C;AAAA,IACH;AAGA,mBAAe,iBAAiB;AAC9B,UAAI,CAAC,iBAAiB,OAAO;AAC3BF,wBAAAA,aAAa,EAAE,OAAO,UAAU,MAAM,OAAM,CAAE;AAC9C;AAAA,MACD;AACD,UAAI;AACF,cAAMD,WAAS,UAAC,oBAAoB,iBAAiB,OAAO,OAAO;AACnE,gBAAQ,MAAM,SAAS;AACvBC,wBAAAA,aAAa,EAAE,OAAO,SAAS,MAAM,UAAS,CAAE;AAAA,MACpD,QAAU;AACNA,wBAAAA,aAAa,EAAE,OAAO,UAAU,MAAM,OAAM,CAAE;AAAA,MAC/C;AAAA,IACH;AAGA,mBAAe,kBAAkB;AAC/B,UAAI,CAAC,iBAAiB,OAAO;AAC3BA,wBAAAA,aAAa,EAAE,OAAO,UAAU,MAAM,OAAM,CAAE;AAC9C;AAAA,MACD;AACD,UAAI;AACF,cAAMD,WAAS,UAAC,oBAAoB,iBAAiB,OAAO,QAAQ;AACpE,gBAAQ,MAAM,SAAS;AACvBC,wBAAAA,aAAa,EAAE,OAAO,SAAS,MAAM,UAAS,CAAE;AAAA,MACpD,QAAU;AACNA,wBAAAA,aAAa,EAAE,OAAO,UAAU,MAAM,OAAM,CAAE;AAAA,MAC/C;AAAA,IACH;AAEA,aAAS,WAAW;AAClB,UAAI,CAAC,UAAU,OAAO;AACpBA,wBAAAA,aAAa,EAAE,OAAO,WAAW,MAAM,OAAM,CAAE;AAC/C;AAAA,MACD;AACDA,sBAAAA,aAAa,EAAE,OAAO,SAAS,MAAM,UAAS,CAAE;AAAA,IAClD;AAEA,aAAS,gBAAgB,OAAO;AAC9BA,mCAAa,EAAE,OAAO,QAAQ,MAAM,IAAI,IAAI,MAAM,QAAQ;AAAA,IAC5D;AAGAG,kBAAM,OAAC,CAAC,YAAY;AAClB,UAAI;AACF,YAAI,WAAW,QAAQ,SAAS;AAC9B,gBAAM,WAAW,KAAK,MAAM,mBAAmB,QAAQ,OAAO,CAAC;AAC/D,kBAAQ,QAAQ,EAAE,GAAG,QAAQ,OAAO,GAAG,SAAU;AAAA,QAClD;AAAA,MACF,SAAQ,GAAG;AAAA,MAEX;AACD,UAAI,mCAAS,IAAI;AACf,qBAAa,QAAQ,OAAO,QAAQ,EAAE;AAAA,MACvC;AACD,UAAI,mCAAS,eAAe;AAC1B,yBAAiB,QAAQ,OAAO,QAAQ,aAAa;AAAA,MACtD;AAAA,IACH,CAAC;AAGDC,kBAAAA,UAAU,YAAY;AACpB,YAAM,QAAQ,gBAAiB;AAC/B,YAAM,MAAM,MAAM,MAAM,SAAS,CAAC;AAClC,UAAI,OAAO,IAAI,uBAAuB;AACpC,cAAM,KAAK,IAAI,sBAAuB;AACtC,YAAI,IAAI;AACN,aAAG,GAAG,WAAW,CAAC,SAAS;AACzB,gBAAI;AAAM,sBAAQ,QAAQ,EAAE,GAAG,QAAQ,OAAO,GAAG,KAAM;AAAA,UAC/D,CAAO;AACD,aAAG,GAAG,eAAe,CAAC,SAAS;AAC7B,gBAAI,6BAAM,SAAS;AACjB,sBAAQ,QAAQ,EAAE,GAAG,QAAQ,OAAO,GAAG,KAAK,QAAS;AAAA,YACtD;AAAA,UACT,CAAO;AAAA,QACF;AAAA,MACF;AAED,UAAI,aAAa,OAAO;AACtB,cAAM,kBAAkB,aAAa,KAAK;AAAA,MAC3C;AAAA,IACH,CAAC;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;ACvVD,GAAG,WAAW,eAAe;"}
